+            'an unterminated replacement string kills the whole eval',
+      );
+      expect(js.contains('\r'), isFalse, reason: 'no raw CR in the JS');
+      expect(js.contains('\t'), isFalse, reason: 'no raw TAB in the JS');
+    });
